#!/bin/sh
# Cloudflare Pages build step for the static demo site (output directory:
# src/GameRagKit.Cli/StudioWeb). Points every page at the GameRagKit server set in the
# Pages project's GAMERAG_SERVER_URL environment variable, e.g.
#   GAMERAG_SERVER_URL=https://gameragkit.up.railway.app
set -eu
: "${GAMERAG_SERVER_URL:?Set GAMERAG_SERVER_URL in the Pages project settings}"
cat > src/GameRagKit.Cli/StudioWeb/server-config.js <<JS
// Generated by deploy/cloudflare-pages-build.sh
window.GAMERAG_SERVER_URL = window.GAMERAG_SERVER_URL || "${GAMERAG_SERVER_URL%/}";
fetch(window.GAMERAG_SERVER_URL + "/health", { cache: "no-store" }).catch(function () {});
JS
echo "Demo pages will call ${GAMERAG_SERVER_URL%/}"
